	for (unsigned int i = 0; i < rules.size(); i++) {
		for (unsigned int j = 0; j < rules[i].right.size(); j++) {
			const string& part = rules[i].right[j];
			//同一个候选式中该非终结符可能出现多次，逐个位置考察
			string::size_type pos = part.find(non_terminal);
